// src/components/FilmGallery.jsx
import React, { useState, useEffect } from 'react';
import FilmCard from './FilmCard';

function FilmGallery() {
  const [films, setFilms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Зверніть увагу: ми використовуємо відносний шлях /films, 
    // і proxy в package.json перенаправить його на http://localhost:5000/films
    fetch('/films') 
      .then(response => {
        if (!response.ok) {
          throw new Error('Failed to fetch films from server.');
        }
        return response.json();
      })
      .then(data => {
        setFilms(data);
        setLoading(false);
      })
      .catch(err => {
        setError("Could not load films from the server. Check if the server is running on port 5000.");
        setLoading(false);
        console.error("Fetch error: ", err);
      });
  }, []);

  if (loading) {
    return <h2>Loading films...</h2>;
  }

  if (error) {
    // Відображає помилку, яку ви бачили раніше, але з поясненням
    return <h2 style={{ color: 'red' }}>Error: {error}</h2>;
  }

  return (
    <div className="film-list-container">
      <h3>Films Library ({films.length} items)</h3>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
        {films.map(film => (
          <FilmCard key={film.id} film={film} />
        ))}
      </div>
      
      {/* Тут може бути ваша логіка управління, як на першому скріншоті */}
      <div className="manage-films-box">
        {/* Ваш UI для сортування та підрахунку часу */}
      </div>
      
    </div>
  );
}

export default FilmGallery;
